  "La formation 2-2-1 sans faille (Lutteurs aux barrières, Hastiers derrière, Runner au centre) ; ses meilleurs tant qu’ils restent sous le seuil de fatigue ; réglages de base équilibrés.": "The flawless 2-2-1 formation (Wrestlers at the barriers, Halberdiers behind, Runner in the centre); fields its best as long as they stay under the fatigue threshold; balanced base settings.",
  "Formation 2 Lutteurs, 2 Hastiers, 1 Runner. Aligne ses meilleurs tant qu’ils sont sous 50 de fatigue. Lutteurs aux barrières, Hastiers derrière, Runner au centre.": "Formation of 2 Wrestlers, 2 Halberdiers, 1 Runner. Fields its best as long as they are under 50 fatigue. Wrestlers at the barriers, Halberdiers behind, Runner in the centre.",
