  "2 Lutteurs, 3 Hastiers, aucun Runner. Ligne en retrait. Protège ses blessés et souffle souvent.": "2 Wrestlers, 3 Halberdiers, no Runner. Line held back. Protects its wounded and catches its breath often.",
