  "2 Runners, 2 Lutteurs, 1 Hastier. Ligne avancée. Ses Runners cherchent le dos de vos combattants ; il souffle rarement.": "2 Runners, 2 Wrestlers, 1 Halberdier. Advanced line. Its Runners go for your fighters' backs; it rarely catches its breath.",
