  "Toute l’équipe sur un même flanc. Tous frappent la même cible jusqu’au KO.": "The whole team on one flank. Everyone strikes the same target until the KO.",
  "La Guerre d’usure": "The War of Attrition",
  "Rotation : personne ne combat fatigué tant qu’un remplaçant est frais ; vise les adversaires épuisés ; Hastiers à distance ; souffle tôt et longtemps.": "Rotation: nobody fights tired while a fresh substitute is available; targets exhausted opponents; Halberdiers at range; catches its breath early and for long.",
  "N’aligne pas ses combattants fatigués s’il a des remplaçants frais. Vise vos combattants les plus fatigués et souffle souvent.": "Doesn't field its tired fighters if it has fresh substitutes. Targets your most tired fighters and catches its breath often.",
