  "Pain au méteil": "Maslin bread",
  "Une miche de froment et de seigle, dense et nourrissante. Le combattant qui la mange retrouve toutes ses forces : sa fatigue tombe à 0.": "A loaf of wheat and rye, dense and nourishing. The fighter who eats it regains all his strength: his fatigue drops to 0.",
  "Hypocras": "Hippocras",
  "Vin épicé et miellé qui échauffe le sang. Donné pendant le placement, il accorde +10 % de dégâts finaux au combattant pour la manche qui suit. Un seul à la fois.": "Spiced, honeyed wine that warms the blood. Given during placement, it grants the fighter +10% final damage for the following round. Only one at a time.",
