  "La Lice dressée dans une clairière, entre arbres, buissons et rochers.": "The Lists set up in a clearing, among trees, bushes and rocks.",
  "Grève sablonneuse": "Sandy shore",
  "Une Lice installée sur un terrain de sable, parmi les dunes et les herbes sèches.": "Lists set up on sandy ground, among dunes and dry grass.",
  "Place du village": "Village square",
  "La Lice montée pour un jour au cœur du village : maisons, échoppes, tonneaux et charrettes.": "The Lists set up for a day in the heart of the village: houses, stalls, barrels and carts.",
  "Cour du château": "Castle courtyard",
  "La Lice dressée dans la cour d’un château, au pied des remparts pavoisés.": "The Lists set up in a castle courtyard, at the foot of the bannered ramparts.",
  "Campement militaire": "Military camp",
  "La Lice au milieu d’un camp d’hommes d’armes : tentes rayées, feux, râteliers et bannières.": "The Lists in the middle of a camp of men-at-arms: striped tents, fires, racks and banners.",
  "Abords du château": "Castle grounds",
  "La Lice de la Reine, sur l’herbe au pied des remparts : pierre, bois et chemin pavé.": "The Queen's Lists, on the grass at the foot of the ramparts: stone, wood and a paved path.",
  "La Lice de la Coupe de France, dans les vignes, au pied des remparts du Château de Gabarnac.": "The Coupe de France Lists, in the vineyards, at the foot of the ramparts of Château de Gabarnac.",
