  "Corrections": "Fixes",
  "Entraînement, succès et son": "Training, achievements and sound",
  "Ma Lice d’entraînement : vos combattants s’affrontent entre eux (1 contre 1, 3 contre 3, 5 contre 5) avec les vraies règles, sans aucune conséquence, et un journal qui explique chaque coup.": "My Training Lists: your fighters face each other (1 against 1, 3 against 3, 5 against 5) with the real rules, without any consequence, and a log that explains every blow.",
  "Deux talents par combattant : le second se révèle gratuitement au Scriptorium ; avec deux talents, on choisit lequel remplacer.": "Two talents per fighter: the second is revealed for free at the Scriptorium; with two talents, you choose which one to replace.",
  "40 succès à conquérir, réunis dans la Salle des exploits — dont des exploits secrets.": "40 achievements to conquer, gathered in the Hall of Feats — including secret feats.",
  "Le son : trois musiques en fondu enchaîné, une ambiance par lieu et des effets sonores (coups, KO, fanfare, exploits), tout réglable dans les Options.": "Sound: three cross-fading music tracks, an ambience for each place and sound effects (blows, KO, fanfare, feats), all adjustable in the Options.",
  "Une fatigue qui compte : courbatures après chaque combat, combattants fatigués moins efficaces, épuisés envoyés au Banquet.": "Fatigue that matters: aches after every fight, tired fighters less effective, exhausted ones sent to the Banquet.",
  "Coupe de France : la fatigue est remise à 0 à l’entrée dans la compétition, puis se garde d’un combat à l’autre.": "Coupe de France: fatigue is reset to 0 on entering the competition, then carries over from one fight to the next.",
  "Sept nouvelles partitions d’écusson (15 au choix).": "Seven new shield partitions (15 to choose from).",
  "Écran principal : un emblème différent à chaque ouverture du jeu.": "Main screen: a different emblem each time the game opens.",
  "Options accessibles en jeu, sans quitter la partie.": "Options available in game, without leaving the game.",
  "Patch Notes resserrées : seules les versions majeures et leurs grosses évolutions.": "Tighter Patch Notes: only major versions and their big changes.",
  "Le vrai béhourd": "The real béhourd",
  "Les quatre saisons : une année de 100 jours qui change le monde (rivière asséchée, forêt enneigée…), les combats et les talents saisonniers.": "The four seasons: a 100-day year that changes the world (dried-up river, snowy forest…), the fights and the seasonal talents.",
  "50 talents aux vrais effets, en combat comme hors combat ; les artefacts de Flavia deviennent une amélioration par paliers.": "50 talents with real effects, in and out of combat; Flavia's artefacts become a tiered upgrade.",
  "Le Centre : configurations d’affectation enregistrées et réappliquées d’un clic ; palmarès sur les fiches de club.": "The Centre: assignment setups saved and reapplied in one click; records on club sheets.",
  "La position avant tout : Lutteur redoutable contre la barrière, Hastier qui frappe par-dessus l’épaule, Runner qui prend à revers ; fin de la boucle des classes.": "Position above all: a Wrestler formidable against the barrier, a Halberdier striking over the shoulder, a Runner taking the enemy from behind; the end of the class loop.",
  "La fatigue évolue pendant la manche : on s’épuise, on souffle, on récupère au sol et pendant les temps morts.": "Fatigue changes during the round: fighters wear out, catch their breath, recover on the ground and during time-outs.",
  "Huit manières de combattre pour les équipes adverses, de l’Ordonnance au Chasseur de têtes.": "Eight ways of fighting for opposing teams, from the Ordinance to the Headhunter.",
  "150 PV par combattant : des manches plus longues, plus de place au placement.": "150 HP per fighter: longer rounds, more room for placement.",
  "Carnet de bord repensé : un sceau pour le combat du jour, une tuile par domaine.": "Redesigned logbook: a seal for the day's fight, a tile per area.",
  "Effets des talents et des moments forts : runes, survie à 1 PV, combos, gros coups, pétales et étincelles de victoire.": "Effects for talents and highlights: runes, surviving at 1 HP, combos, big hits, victory petals and sparks.",
  "Talents, palmarès et Coupe": "Talents, records and Cup",
  "Le Scriptorium et les talents : un Bureau d’étude où chaque combattant révèle son talent ; la Professeure Flavia, son chat, un second bureau et les artefacts.": "The Scriptorium and talents: a Study Desk where each fighter reveals his talent; Professor Flavia, her cat, a second desk and the artefacts.",
  "Palmarès et trophées : armoire à trophées et pancarte des classements dans la Taverne, historique des clubs.": "Records and trophies: trophy cabinet and rankings board in the Tavern, club histories.",
  "Statut « Elite » pour les 16 meilleurs combattants de France.": "“Elite” status for the 16 best fighters in France.",
  "Huit nouveaux lieux de départ : six par Terre.": "Eight new starting places: six per Land.",
  "La Coupe de France se dispute à la fin de chaque saison : arbre final, récompenses en deniers à chaque victoire.": "The Coupe de France is played at the end of each season: knockout tree, deniers rewarded for each win.",
  "Un royaume plus rude : recrues de 2,5★ et plus plus chères, potentiel plus rare, clubs adverses qui progressent moins vite.": "A harsher kingdom: recruits of 2.5★ and above cost more, potential is rarer, opposing clubs progress more slowly.",
  "Un Bourg qui s’anime : campement de tentes, artisans au travail, habitants, chiens et oiseaux.": "A Town that comes alive: tent camp, craftsmen at work, inhabitants, dogs and birds.",
  "Le domaine et la Coupe de France": "The domain and the Coupe de France",
  "La Coupe de France au Château de Gabarnac : 54 compagnies, poules puis tableau final.": "The Coupe de France at Château de Gabarnac: 54 companies, groups then a knockout bracket.",
  "Se déplacer sur la carte : les chemins du Centre mènent à la Taverne et au Bourg.": "Getting around the map: the Centre's paths lead to the Tavern and the Town.",
  "Un écran principal vivant, avec les Patch Notes.": "A lively main screen, with the Patch Notes.",
  "Équipes enregistrées : trois équipes de 8 combattants, rappelées d’un clic.": "Saved teams: three teams of 8 fighters, recalled in one click.",
  "Le potentiel fixe un plafond aux compétences.": "Potential sets a ceiling on skills.",
  "Les équipes adverses adoptent un comportement selon leur force.": "Opposing teams adopt a behaviour according to their strength.",
  "Taverne : le prix d’une recrue dépend de ses étoiles.": "Tavern: a recruit's price depends on his stars.",
  "Placement dans la Lice repensé : votre équipe, la Lice et les adversaires sur un seul écran.": "Placement in the Lists redesigned: your team, the Lists and the opponents on a single screen.",
  "Un camp vivant": "A living camp",
  "Le Centre s’anime : les combattants nagent, mangent, luttent, frappent les mannequins, chargent le foin et fendent du bois.": "The Centre comes alive: fighters swim, eat, wrestle, strike the dummies, charge the hay and split wood.",
