  " (couleur {0})": " (colour {0})",
  "Administration": "Administration",
  "Outils de développement : clubs, statistiques, ressources, temps, sauvegardes… Un code d’accès est demandé.": "Development tools: clubs, stats, resources, time, saves… An access code is required.",
  "Ouvrir le module Admin": "Open the Admin module",
  "Cliquez sur le Bureau d’étude pour envoyer un combattant révéler ses talents (deux au plus), ou sur la Professeure Flavia pour améliorer le Scriptorium. La porte ramène au Centre.": "Click on the Study Desk to send a fighter to reveal his talents (two at most), or on Professor Flavia to upgrade the Scriptorium. The door leads back to the Centre.",
