  " · premier talent": " · first talent",
  "Talents {0}s": "{0} talents",
  "L’intérieur du Scriptorium en vue isométrique": "The inside of the Scriptorium in isometric view",
  "Copistes, moines et baillis veillent sur les savoirs de la citadelle. Au Bureau d’étude, un combattant révèle ses talents ; la Professeure Flavia y veille.": "Copyists, monks and bailiffs watch over the citadel's knowledge. At the Study Desk, a fighter reveals his talents; Professor Flavia watches over it.",
  "La porte — sortir du Scriptorium ({0}).": "The door — leave the Scriptorium ({0}).",
  "La Professeure Flavia — cliquez pour améliorer le Bureau d’étude ou choisir un artefact.": "Professor Flavia — click to upgrade the Study Desk or choose an artefact.",
  "Bureau d’étude — {0} étudie{1} ({2} / {3}). Cliquez pour suivre les études{4}.": "Study Desk — {0} studying ({2} / {3}). Click to follow the studies{4}.",
  " ou en lancer une autre": " or start another one",
  "Bureau d’étude — libre. Cliquez pour choisir le combattant qui étudiera.": "Study Desk — free. Click to choose the fighter who will study.",
  "Libre · {0} place{1}": "Free · {0} slot{1}",
  "{0} — encore {1}": "{0} — {1} left",
  "{0} combattants en étude": "{0} fighters studying",
  "Le Bureau d’étude": "The Study Desk",
  "{0} / {1} place{2}": "{0} / {1} slot{2}",
  "Personne n’étudie en ce moment.": "Nobody is studying at the moment.",
  "Choisir un combattant": "Choose a fighter",
  "Chances à la révélation — {0} {1}": "Chances on revelation — {0} {1}",
  "👑 La Professeure Flavia": "👑 Professor Flavia",
  "Bureau d’étude : {0} place{1} · {2}.": "Study Desk: {0} slot{1} · {2}.",
  "Parler à la Professeure Flavia": "Talk to Professor Flavia",
  "L’étude": "The study",
  "Un combattant en étude ne s’entraîne pas et ne combat pas. À la fin, un talent se révèle. Chaque combattant peut avoir deux talents : le premier et le second se révèlent gratuitement. Avec deux talents, une nouvelle étude ({0}) remplace celui qu’on choisit, à la révélation. Interrompue, l’étude ne révèle rien et n’est pas remboursée.": "A fighter in study doesn't train or fight. At the end, a talent is revealed. Each fighter can have two talents: the first and the second are revealed for free. With two talents, a new study ({0}) replaces the one you choose, on revelation. If interrupted, the study reveals nothing and is not refunded.",
  "Fin de l’étude : jour {0} — encore {1}.": "End of the study: day {0} — {1} left.",
  "{0} sur {1}{2}.": "{0} out of {1}{2}.",
  "Choisissez le combattant qui étudiera.": "Choose the fighter who will study.",
  "{0} : {1} d’étude": "{0}: {1} of study",
  "Talent à remplacer": "Talent to replace",
  "Premier talent": "First talent",
  "Second talent": "Second talent",
  "Étudier le combattant : {0}": "Study the fighter: {0}",
  "Talent{0} actuel{1} : ": "Current talent{0}: ",
  "Durée : {0} (fin le jour {1})": "Length: {0} (ends on day {1})",
  "Coût : {0}": "Cost: {0}",
  "Il garde {0} jusqu’à la révélation du nouveau talent, qui le remplacera ; {1} reste acquis.": "He keeps {0} until the new talent is revealed, which will replace it; {1} remains acquired.",
  "son autre talent": "his other talent",
  "Le second talent s’ajoute à {0} : jamais le même.": "The second talent is added to {0}: never the same one.",
  "Le Bureau d’étude — choisir un combattant": "The Study Desk — choose a fighter",
  "La durée dépend du potentiel. Chaque combattant peut avoir deux talents : le premier et le second se révèlent gratuitement ; avec deux talents, en remplacer un (au choix) coûte {0}.": "The length depends on potential. Each fighter can have two talents: the first and the second are revealed for free; with two talents, replacing one (your choice) costs {0}.",
  " Coût : {0}, non remboursés en cas d’interruption. Le nouveau talent remplacera {1} ({2} talent), qu’il garde jusqu’à la révélation ; {3} reste acquis.": " Cost: {0}, not refunded if interrupted. The new talent will replace {1} ({2} talent), which he keeps until the revelation; {3} remains acquired.",
  " Son second talent s’ajoutera à {0} (gratuit).": " His second talent will be added to {0} (free).",
  "Remplacer un talent ?": "Replace a talent?",
  "Révéler son second talent ?": "Reveal his second talent?",
  "Lancer l’étude ?": "Start the study?",
  "{0} étudiera {1} au Scriptorium (fin le jour {2}). Il quittera son activité du Centre et ne pourra ni s’entraîner ni combattre jusqu’à la fin de son étude.{3}": "{0} will study for {1} at the Scriptorium (ends on day {2}). He will leave his Centre activity and won't be able to train or fight until the end of his study.{3}",
  "{0} commence son étude au Scriptorium ({1}{2}).": "{0} starts his study at the Scriptorium ({1}{2}).",
  "Interrompre l’étude ?": "Interrupt the study?",
  "{0} quittera le Bureau d’étude sans révéler de talent : le temps déjà passé est perdu{1}.{2} Il redeviendra disponible aussitôt.": "{0} will leave the Study Desk without revealing a talent: the time already spent is lost{1}.{2} He will be available again immediately.",
  ", les {0} ne sont pas remboursés": ", the {0} are not refunded",
  " Il garde {0}.": " He keeps {0}.",
  "L’étude de {0} est interrompue : aucun nouveau talent.": "{0}'s study is interrupted: no new talent.",
  "Actif": "Active",
  "Remplacé": "Replaced",
  "À acheter": "To buy",
  "Verrouillé": "Locked",
  "« Un esprit bien guidé trouve vite sa voie. Offrez à vos combattants de meilleures conditions d’étude, et les talents les plus rares se révéleront. »": "“A well-guided mind soon finds its way. Give your fighters better conditions for study, and the rarest talents will be revealed.”",
  "Amélioration du Bureau d’étude": "Study Desk upgrade",
  "Actuellement : {0} place{1}": "Currently: {0} slot{1}",
  "{0} Achat unique.": "{0} One-time purchase.",
  "✔ Amélioration acquise": "✔ Upgrade acquired",
  "Artefacts": "Artefacts",
  "Une amélioration par paliers : chaque artefact débloque le suivant et le remplace une fois acheté. Seul le dernier acquis est actif ; ses chances s’appliquent au moment où un talent se révèle, études en cours comprises.": "A tiered upgrade: each artefact unlocks the next one and replaces it once bought. Only the last one acquired is active; its chances apply when a talent is revealed, studies in progress included.",
  "Départ": "Start",
  "✔ Acquis": "✔ Acquired",
  "Un second Bureau d’étude est installé (−{0}) : deux combattants peuvent étudier en même temps.": "A second Study Desk is installed (−{0}): two fighters can study at the same time.",
  "{0} acquis (−{1}) : ses chances s’appliquent désormais.": "{0} acquired (−{1}): its chances now apply.",
  "Survolez un combattant pour voir sa spécialité et ses étoiles ; cliquez pour sa fiche. Le tavernier se tient derrière le comptoir ; la pancarte affiche les classements, l’armoire vos trophées ; la porte ramène au Centre.": "Hover over a fighter to see his speciality and stars; click for his card. The tavern keeper stands behind the counter; the board shows the rankings, the cabinet your trophies; the door leads back to the Centre.",
  "L’intérieur de la Taverne en vue isométrique": "The inside of the Tavern in isometric view",
  "Des combattants cherchent une compagnie. Approchez-vous, observez-les, et parlez au tavernier.": "Fighters are looking for a company. Come closer, watch them, and talk to the tavern keeper.",
  "Vous disposez de {0} deniers. Effectif : {1} / {2} combattants.": "You have {0} deniers. Squad: {1} / {2} fighters.",
  "Effectif complet ({0} / {1}) : aucun recrutement possible. Congédiez un combattant depuis sa fiche (La Compagnie) pour libérer une place.": "Squad full ({0} / {1}): no recruitment possible. Dismiss a fighter from his sheet (The Company) to free a place.",
  "🍺 Le tavernier": "🍺 The tavern keeper",
