  "Les études": "The studies",
  "Préparer l’entraînement": "Prepare the training",
  "Une interface pensée pour le téléphone : la carte en plein écran, un dock flottant, la Compagnie en liste et fiche, le combat en main de cartes.": "An interface designed for phones: full-screen map, a floating dock, the Company as list and sheet, combat as a hand of cards.",
  "Le jeu dans la poche": "The game in your pocket",
  "Interface mobile (application Android) : le Centre, le Bourg, la Taverne, le Scriptorium et Ma Lice s’affichent en plein écran ; un bandeau en haut (compagnie et jour, prochain événement, deniers, menu), les lieux à gauche, un dock flottant en bas (Compagnie, Domaine, Coffre, Ligue) et un gros bouton « Jour suivant », qui devient « Combattre » un jour de combat.": "Mobile interface (Android app): the Centre, the Town, the Tavern, the Scriptorium and My Lists are shown full screen; a top bar (company and day, next event, deniers, menu), the places on the left, a floating dock at the bottom (Company, Area, Chest, League) and a big “Next day” button, which becomes “Fight” on a fight day.",
  "Ce qui se trouvait sous la carte (affectations, artisans, recrues, études) remonte du bas dans un volet ; un toucher sur le bandeau ouvre le calendrier complet, le menu réunit sauvegarde, succès, options, Almanach et menu principal.": "What used to sit under the map (assignments, craftsmen, recruits, studies) slides up from the bottom in a panel; tapping the top bar opens the full calendar, and the menu gathers saving, achievements, options, the Almanac and the main menu.",
  "La Compagnie sur téléphone : la liste des combattants à gauche, filtrable par classe, et la fiche complète à droite, sans fenêtre à ouvrir.": "The Company on phones: the list of fighters on the left, filterable by class, and the full sheet on the right, with no window to open.",
  "Le combat sur téléphone : la lice en plein écran ; vos combattants à placer forment une main de cartes (étoiles, quatre compétences, celle de la classe en avant, fatigue) et la fiche du combattant choisi rappelle ses compétences, son état, ses talents et son rôle. La manche se regarde en plein écran.": "Combat on phones: the lists full screen; the fighters you place form a hand of cards (stars, four skills with the class's own highlighted, fatigue) and the chosen fighter's sheet recalls skills, condition, talents and role. The round plays full screen.",
  "Taverne : le potentiel des recrues (flammes) s’affiche sur leur carte, sans ouvrir leur fiche.": "Tavern: the recruits' potential (flames) is shown on their card, without opening their sheet.",
  "Le bouton retour du téléphone referme aussi le volet d’un lieu.": "The phone's back button also closes a place's panel.",
  "Blason": "Coat of arms",
  "Étapes": "Steps",
  "Version {0} · ": "Version {0} · ",
  "Continuer": "Continue",
  "Nouvelle partie": "New game",
  "Entrer en jeu sur téléphone": "Starting a game on the phone",
  "Application Android : l’écran principal tient sans défiler (titre à gauche, menu à droite) et propose « Continuer », qui reprend la dernière partie au Centre.": "Android app: the main screen fits without scrolling (title on the left, menu on the right) and offers “Continue”, which resumes the latest game at the Centre.",
  "Nouvelle partie sur téléphone : directement la carte des Terres de France en plein écran, le choix du lieu à droite ; le blason et le capitaine s’affichent en grand à gauche, les choix à droite ; les trois étapes sont rappelées en bas.": "New game on the phone: straight to the full-screen map of France's Lands, the place chosen on the right; the coat of arms and the captain are shown large on the left, the choices on the right; the three steps are recalled at the bottom.",
  "Sur téléphone, le carnet de bord présente le jour à gauche et le récit à droite ; la Coupe de France montre Gabarnac en plein écran avec le prochain combat et la poule à droite ; Ma Lice s’ouvre sur la lice, le volet fermé.": "On the phone, the logbook shows the day on the left and the story on the right; the Coupe de France shows Gabarnac full screen with the next fight and the group on the right; My Lists opens on the lists, panel closed.",
  "La version ordinateur ne change pas.": "The computer version does not change.",
  "Le bassinet fleuri": "The flowering bascinet",
  "Application Android : un écran de démarrage — un bassinet du temps de Charles VI posé dans l’herbe, que la végétation envahit (herbes, liane, fleurs), puis les lettres « BZW ». Un toucher le passe.": "Android app: a start screen — a bascinet from the time of Charles VI lying in the grass, overgrown by vegetation (grass, vine, flowers), then the letters “BZW”. A tap skips it.",
  "Sur téléphone, chaque fin de combat ramène au Centre.": "On the phone, every fight ends back at the Centre.",
  "Sur téléphone, la Taverne et les autres lieux s’ouvrent sur leur carte : le volet des textes reste fermé jusqu’à ce qu’on le demande.": "On the phone, the Tavern and the other places open on their map: the text panel stays closed until you ask for it.",
  "La lice au creux de la main": "The lists in the palm of your hand",
  "Sur téléphone, l’effectif engagé et le choix des combattants de chaque manche se font en grandes cartes (classe, étoiles, compétences, fatigue) ; l’adversaire et les actions restent à portée du pouce, à droite.": "On the phone, the match squad and the fighters for each round are picked from large cards (class, stars, skills, fatigue); the opponent and the actions stay within thumb's reach, on the right.",
  "Sur téléphone, le résultat d’une manche tient sur un écran : vainqueur, score, meilleur combattant, et pour chacun mises à terre, dégâts et fatigue.": "On the phone, a round result fits on one screen: winner, score, best fighter, and for each fighter takedowns, damage and fatigue.",
  "Sur téléphone, la fin du combat affiche en grand la victoire ou la défaite, les points, la recette et les manches ; le classement à côté, les autres combats et les courbatures repliés.": "On the phone, the end of the fight shows victory or defeat in large letters, the points, the takings and the rounds; the standings alongside, the other fights and the soreness folded away.",
  "Application Android : la Compagnie, le Championnat et les autres pages sont de nouveau centrés (la marge de l’encoche était comptée deux fois).": "Android app: the Company, the Championship and the other pages are centred again (the notch margin was counted twice).",
  "Sur téléphone, le bouton rond « Combattre » s’affiche sur une seule ligne.": "On the phone, the round “Fight” button fits on a single line.",
  "Équipe type": "Best team",
  "Tout décocher": "Untick all",
  "Manche décisive !": "Deciding round!",
  "La fatigue des manches précédentes compte : préférez les combattants reposés.": "Fatigue from earlier rounds counts: prefer rested fighters.",
  "Tous vos combattants engagés sont KO.": "All your committed fighters are KO.",
  "KO pour ce combat": "KO for this fight",
  "Dégâts": "Damage",
  "Meilleur combattant : ": "Best fighter: ",
  "Égalité 1 – 1 : une manche décisive va se jouer.": "1 – 1 draw: a deciding round will be fought.",
