  "Dernière journée : la saison {0} est terminée.": "Last matchday: season {0} is over.",
  "Adversaire : {0}": "Opponent: {0}",
  "Une interface pensée pour le téléphone : la carte en plein écran, un dock flottant, la Compagnie en liste et fiche, le combat en grandes cartes du choix de l’effectif jusqu’à la victoire.": "An interface designed for the phone: the full-screen map, a floating dock, the Company as list and sheet, the fight in large cards from picking the squad to victory.",
  "Le heaume à l’épée": "The helm and the sword",
  "Application Android : nouvelle icône — le heaume et l’épée sur fond de bannière.": "Android app: new icon — the helm and the sword over a banner.",
  "Sur téléphone, la partie est sauvegardée dès que le jeu passe en arrière-plan (sauvegarde automatique active, jamais en plein combat) : Android peut fermer l’application sans rien perdre.": "On the phone, the game is saved as soon as it goes to the background (autosave on, never mid-fight): Android can close the app without losing anything.",
  "Sur téléphone, les scènes (Centre, Bourg, Taverne, Scriptorium, Ma Lice, combat) se dessinent à 30 images par seconde : moins de calcul, moins de batterie.": "On the phone, the scenes (Centre, Borough, Tavern, Scriptorium, Ma Lice, fight) are drawn at 30 frames per second: less computing, less battery.",
  "Sur téléphone, en arrière-plan, plus rien ne se dessine et le son se tait ; il reprend au retour.": "On the phone, in the background, nothing is drawn and the sound goes quiet; it resumes when you return.",
  "Sur un petit téléphone (peu de cœurs ou de mémoire), les effets visuels « complets » passent d’eux-mêmes en « réduits ».": "On a modest phone (few cores or little memory), “full” visual effects switch to “reduced” by themselves.",
  "La bulle et la chanson": "The bubble and the song",
  "Sur téléphone, toucher un talent (fiche d’un combattant, Taverne, combat…) affiche une bulle qui explique son effet ; un autre toucher la referme.": "On the phone, tapping a talent (fighter sheet, Tavern, fight…) shows a bubble explaining its effect; another tap closes it.",
  "Application Android : l’écran de démarrage a son air, « Girls » ; la musique du jeu prend le relais ensuite.": "Android app: the start screen has its own tune, “Girls”; the game music takes over afterwards.",
  "Sur téléphone, la création de l’équipe et du capitaine n’ouvre plus le clavier d’office : il s’ouvre quand on touche le champ du nom (de même dans les fenêtres de saisie).": "On the phone, creating the team and the captain no longer opens the keyboard by itself: it opens when you tap the name field (likewise in input windows).",
  "Béhourd Management — Gestion de compagnie": "Béhourd Management — Company management",
  "Le jeu s’appelle désormais « Béhourd Management » : écran principal, onglet du navigateur et application Android.": "The game is now called “Béhourd Management”: main screen, browser tab and Android app.",
  "La Coupe au pouce": "The Cup at your fingertips",
  "Sur téléphone, le menu (bouton en haut à droite) s’ouvre en volet sur le côté : état de la sauvegarde, grand bouton Sauvegarder, Succès, L’Almanach, Options, Patch Notes, et Menu principal à part en bas.": "On the phone, the menu (top-right button) opens as a side panel: save status, a large Save button, Achievements, L’Almanach, Options, Patch Notes, and Main menu set apart at the bottom.",
  "Sur téléphone, le tirage au sort de la Coupe de France montre la dernière compagnie tirée en grand et les neuf poules en blasons ; toucher une poule donne le nom de ses compagnies.": "On the phone, the Coupe de France draw shows the last company drawn in large and the nine groups as coats of arms; tapping a group gives its companies’ names.",
  "Sur téléphone, le Château de Gabarnac s’affiche en plein écran avec le prochain combat, le bouton « Combattre » et un dock : Gabarnac, Tableau, Arbre, Résultats.": "On the phone, the Château de Gabarnac is shown full screen with the next fight, the “Fight” button and a dock: Gabarnac, Board, Bracket, Results.",
  "Sur téléphone, le tableau de la Coupe s’ouvre en volet : rubriques à gauche, poules A à I en onglets avec les blasons ; l’arbre final se lit tour par tour, le parcours de la compagnie en or.": "On the phone, the Cup board opens as a panel: sections on the left, groups A to I as tabs with coats of arms; the final bracket reads round by round, the company’s path in gold.",
  "Sur téléphone, la carte du château s’arrête au-dessus du dock : le tableau de la Coupe n’est plus caché.": "On the phone, the castle map stops above the dock: the Cup board is no longer hidden.",
  "Sur téléphone, « Abandonner la Coupe », Sauvegarder et Menu principal passent dans le menu de la Coupe.": "On the phone, “Abandon the Cup”, Save and Main menu move into the Cup menu.",
  "Une interface pensée pour le téléphone : la carte en plein écran, un dock flottant, la Compagnie en liste et fiche, le combat en grandes cartes du choix de l’effectif jusqu’à la victoire, la Coupe de France au pouce.": "An interface designed for the phone: the full-screen map, a floating dock, the Company as list and sheet, the fight in large cards from picking the squad to victory, the Coupe de France at your fingertips.",
