  "Forêt-Noire": "Black Forest",
  "Forêt de Białowieża": "Białowieża Forest",
  "Massif du Mont-Blanc": "Mont Blanc massif",
  "Cirque de Gavarnie": "Cirque de Gavarnie",
  "Les Dolomites": "The Dolomites",
  "Picos de Europa": "Picos de Europa",
  "Abbaye de Jumièges": "Jumièges Abbey",
  "Château de Montségur": "Montségur Castle",
  "Rocca Calascio": "Rocca Calascio",
  "Tintagel": "Tintagel",
  "Skellig Michael": "Skellig Michael",
  "Sognefjord": "Sognefjord",
  "Glencoe": "Glencoe",
  "Connemara": "Connemara",
