  "Fureur du Nord": "Northern Fury",
  "Sous 50 % de ses PV : +20 % de dégâts finaux, et la fatigue ne le pénalise plus.": "Below 50% of his HP: +20% final damage, and fatigue no longer penalises him.",
  "Ascète des Météores": "Ascetic of the Meteora",
  "Rester debout ne le fatigue pas pendant les manches, et ses pénalités de fatigue ne commencent qu’à 90.": "Standing does not tire him during rounds, and his fatigue penalties only start at 90.",
  "Druide de Brocéliande": "Druid of Brocéliande",
  "Une fois par manche, soigne de 40 PV un allié qui tombe sous 25 % de ses PV.": "Once per round, heals 40 HP to an ally who falls below 25% of his HP.",
  "Ours de Białowieża": "Bear of Białowieża",
  "−15 % de dégâts reçus et +10 % d’Endurance en combat.": "−15% damage taken and +10% Endurance in combat.",
  "Lame d’Avalon": "Blade of Avalon",
  "Son premier coup de chaque manche : +40 % de dégâts finaux, et l’aléa est tiré deux fois (le meilleur est gardé).": "His first strike of each round: +40% final damage, and the random roll is drawn twice (the best is kept).",
  "Œil de Skellig": "Eye of Skellig",
  "Vise de préférence l’adversaire le plus blessé, et +12 % de dégâts finaux contre un adversaire sous 50 % de ses PV.": "Prefers to target the most wounded opponent, and +12% final damage against an opponent below 50% of his HP.",
  "Avalanche": "Avalanche",
  "Deux coups de plus dans ses combos, et se déplace 15 % plus vite dans la lice.": "Two more strikes in his combos, and moves 15% faster in the lists.",
  "Dernier rempart": "Last Bulwark",
  "Dernier debout de sa compagnie dans la manche : +30 % de dégâts finaux et −20 % de dégâts reçus.": "Last one standing from his company in the round: +30% final damage and −20% damage taken.",
  "Écho des cimes": "Echo of the Peaks",
  "+7 % de dégâts finaux et −5 % de dégâts reçus pour tous les combattants de sa manche (lui compris).": "+7% final damage and −5% damage taken for all fighters of his round (himself included).",
  "Feu follet": "Will-o’-the-wisp",
  "15 % de chances d’esquiver chaque coup reçu : il ne subit alors aucun dégât.": "15% chance to dodge each strike received: he then takes no damage.",
  "Soin": "Healing",
  "Les vieux chênes y gardent les secrets de Merlin.": "The old oaks keep Merlin’s secrets there.",
  "Des sapins si serrés que le jour n’y entre pas.": "Firs so dense that daylight never gets in.",
  "Les bisons y règnent encore sur les sous-bois.": "Bison still rule the undergrowth there.",
  "La montagne maudite, que nul n’a encore vaincue.": "The cursed mountain, which no one has yet conquered.",
  "Une muraille de roche où tombent les cascades.": "A wall of rock where waterfalls tumble.",
  "Des tours de pierre pâle qui rougissent au couchant.": "Towers of pale stone that redden at sunset.",
  "Les premiers sommets qu’aperçoivent les marins.": "The first peaks that sailors catch sight of.",
  "Les plus belles ruines du royaume, dit-on.": "The finest ruins in the realm, they say.",
  "Comté de Foix (France)": "County of Foix (France)",
  "Un nid d’aigle où les derniers parfaits ont résisté.": "An eagle’s nest where the last Perfects held out.",
  "La forteresse la plus haute des Apennins.": "The highest fortress in the Apennines.",
  "Là où naquit le roi Arthur, face à la mer.": "Where King Arthur was born, facing the sea.",
  "Un rocher, des moines, et l’océan tout autour.": "A rock, some monks, and the ocean all around.",
  "Le plus long des fjords, où dorment les drakkars.": "The longest of fjords, where the longships sleep.",
  "Highlands (Écosse)": "Highlands (Scotland)",
  "Une vallée de bruyère et de brume, et ses vieilles pierres.": "A valley of heather and mist, and its old stones.",
  "Des landes, des lacs, et le vent pour seul maître.": "Moors, lakes, and the wind as sole master.",
  "Thessalie (Grèce)": "Thessaly (Greece)",
  "Des monastères perchés au sommet des rochers.": "Monasteries perched on top of the rocks.",
