  "L’expédition sera perdue, Ferveurs comprises, et sans récompense. Les combattants rentrent avec leur fatigue.": "The expedition will be lost, Fervours included, with no reward. The fighters come home with their fatigue.",
  "🏆 Retour de l’expédition singulière": "🏆 Back from the singular expedition",
  "Rentrer au domaine": "Return to the estate",
